import React from 'react';
import './booking-timeline.css';

const BookingTimeline = ({ itinerary }) => {
  if (!itinerary || itinerary.length === 0) {
    return (
      <div className='timeline_empty'>
        <p>Chưa có lịch trình nào.</p>
      </div>
    );
  }

  return (
    <div className='booking_timeline'>
      <h5 className='fw-bold mb-4'>
        <i className='ri-time-line me-2'></i>Lịch Trình Chi Tiết
      </h5>

      <div className='timeline_container'>
        {itinerary.map((item, index) => (
          <div key={index} className='timeline_item'>
            {/* Timeline Dot */}
            <div className='timeline_marker'>
              <div className='timeline_dot'>
                <i className='ri-map-pin-fill'></i>
              </div>
              {index < itinerary.length - 1 && <div className='timeline_line'></div>}
            </div>

            {/* Content */}
            <div className='timeline_content'>
              <div className='day_header'>
                <h6 className='fw-bold mb-1'>
                  Ngày {item.day || index + 1}
                </h6>
                {item.meals && (
                  <span className='meal_badge'>
                    <i className='ri-restaurant-line me-1'></i>{item.meals}
                  </span>
                )}
              </div>

              <div className='location_info'>
                <p className='location_name mb-2'>
                  <strong>📍 {item.location || 'Chưa xác định'}</strong>
                </p>
              </div>

              {item.description && (
                <div className='description_info'>
                  <p className='mb-0'>{item.description}</p>
                </div>
              )}

              {item.time && (
                <div className='time_info'>
                  <i className='ri-time-line me-1'></i>
                  <small>{item.time}</small>
                </div>
              )}

              {item.activities && item.activities.length > 0 && (
                <div className='activities_list'>
                  <p className='small fw-bold mb-2'>Hoạt động:</p>
                  <ul className='mb-0'>
                    {item.activities.map((activity, idx) => (
                      <li key={idx}>{activity}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Summary Footer */}
      <div className='timeline_footer mt-4 p-3 bg-light rounded'>
        <p className='mb-0'>
          <strong>Tổng cộng {itinerary.length} ngày</strong> | 
          <span className='ms-2'>
            <i className='ri-map-pin-line me-1'></i>
            {itinerary.filter(it => it.location).length} địa điểm
          </span>
        </p>
      </div>
    </div>
  );
};

export default BookingTimeline;
